def update_all():
    with app.app_context():
        ch = Chapter.query.filter(Chapter.title.like('%সুভা%')).first()
        if not ch:
            print("Chapter Subha not found!")
            return
        
        print(f"Updating Chapter: {ch.title} (ID: {ch.id})")
        
        # 1. Update Short Questions
        short_count = 0
        shorts = Question.query.filter_by(chapter_id=ch.id, question_type='short').all()
        for s in shorts:
            if s.id in SHORT_ANSWERS:
                s.short_answer = SHORT_ANSWERS[s.id]
                short_count += 1
            else:
                print(f"Warning: No explicit answer mapped for short ID {s.id}: {s.short_question[:40]}")
        
        # 2. Update CQ Questions
        cq_count = 0
        cqs = Question.query.filter_by(chapter_id=ch.id, question_type='cq').all()
        for c in cqs:
            if c.id in CQ_SOLUTIONS:
                c.cq_solution = CQ_SOLUTIONS[c.id]
                cq_count += 1
            else:
                print(f"Warning: No explicit solution mapped for CQ ID {c.id}")
                
        db.session.commit()
        print(f"Successfully updated {short_count} Short questions and {cq_count} Creative questions!")

if __name__ == '__main__':
    update_all()
